use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let bytes = input.as_array().unwrap().iter().map(|&x| x.as_i64().unwrap()).collect();
    let mut result = String::new();
    for &byte in bytes {
        result.push_str(&format!("{:x}", byte));
    }
    Value::String(result)
}
